    12	
    13	// Matches the hit area of tldraw's .tl-hyperlink-button.
    14	const BUTTON_SIZE = 44;
    15	
    16	// meta is unvalidated, so this is the only guard before an href. Returning the
    17	// parsed form keeps the href identical to what passed validation.
    18	export const getTextShapeLinkUrl = (shape: TLShape): string | undefined => {
    19	  if (shape.type !== "text") return undefined;
    20	  const { url } = shape.meta;
    21	  if (typeof url !== "string" || !T.linkUrl.isValid(url)) return undefined;
    22	  try {
    23	    // linkUrl resolves relative paths against a dummy origin; only absolute URLs render.
    24	    return new URL(url).href;
    25	  } catch {
    26	    return undefined;
    27	  }
    28	};
    29	
    30	// Text bounds hug the glyphs, so the icon sits just outside the right edge
    31	// rather than in the shape corner where geo shapes draw it.
    32	export const TextLinkOverlay = (): JSX.Element => {
    33	  const editor = useEditor();
    34	  const links = useValue<TextLink[]>(
    35	    "textShapeLinks",
    36	    () => {
    37	      const viewport = editor.getViewportPageBounds();
    38	      return editor.getCurrentPageShapes().flatMap((shape) => {
    39	        const url = getTextShapeLinkUrl(shape);
    40	        if (!url) return [];
    41	        const bounds = editor.getShapePageBounds(shape.id);
    42	        if (!bounds || !viewport.collides(bounds)) return [];
    43	        const anchor = editor.pageToViewport({
    44	          x: bounds.maxX,
    45	          y: bounds.midY,
    46	        });
    47	        return [
    48	          {
    49	            id: shape.id,
    50	            url,
    51	            left: anchor.x,
    52	            top: anchor.y - BUTTON_SIZE / 2,
    53	          },
    54	        ];
    55	      });
    56	    },
    57	    [editor],
    58	  );
    59	  const zoomLevel = useValue("zoomLevel", () => editor.getZoomLevel(), [
    60	    editor,
    61	  ]);
    62	
    63	  return (
    64	    <div style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
    65	      {links.map(({ id, url, left, top }) => (
