// Read-only proof for ENG-2227: finds an existing canvas whose text shape
// already carries a link and screenshots it. Never writes to the graph.
export default {
  async ready({ page }) {
    return page.evaluate(() => Boolean(window.roamAlphaAPI));
  },

  async run({ page, outDir }) {
    const target = await page.evaluate(() => {
      const rows = window.roamAlphaAPI.data.q(
        "[:find (pull ?p [:block/uid :node/title :block/props]) :where [?p :node/title]]",
      );
      for (const [p] of rows) {
        const tldraw = p?.[":block/props"]?.["roamjs-query-builder"]?.tldraw;
        const store = tldraw?.store;
        if (!store) continue;
        for (const rec of Object.values(store)) {
          if (
            rec?.typeName === "shape" &&
            rec?.type === "text" &&
            typeof rec?.props?.url === "string" &&
            rec.props.url.length > 0
          ) {
            return {
              uid: p[":block/uid"],
              title: p[":node/title"],
              shapeId: rec.id,
              url: rec.props.url,
              text: rec.props.text,
            };
          }
        }
      }
      return null;
    });

    if (!target) {
      return { found: false, note: "no canvas has a linked text shape yet" };
    }

    await page.evaluate(
      (uid) => window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid } }),
      target.uid,
    );
    await page.waitForSelector(".roamjs-tldraw-canvas-container", {
      timeout: 30000,
    });
    await page.waitForTimeout(3000);

    const zoomed = await page.evaluate((t) => {
      const app = window.tldrawApps?.[t.title];
      if (!app) return false;
      app.select(t.shapeId);
      app.zoomToSelection();
      return true;
    }, target);
    await page.waitForTimeout(1500);

    const geometry = await page.evaluate((shapeId) => {
      const anchor = document.querySelector(".dg-text-link-button");
      if (!anchor) return { anchor: false };
      const shapeEl = document.querySelector(`[data-shape-id="${shapeId}"]`);
      const a = anchor.getBoundingClientRect();
      const s = shapeEl?.getBoundingClientRect();
      return {
        anchor: true,
        classes: anchor.className,
        iconLeft: Math.round(a.left),
        shapeRight: s ? Math.round(s.right) : null,
        overlapsText: s ? a.left < s.right - 2 : null,
      };
    }, target.shapeId);

    await page.screenshot({ path: `${outDir}/eng2227-link-icon.png` });

    return { found: true, page: target.title, zoomed, geometry };
  },
};
