  page.screenshot({ path: `${outDir}/eng2227-${name}.png` });

// Roam returns keyword-prefixed prop keys, so search the stored JSON rather than walk it.
const readPersisted = (page, uid) =>
  page.evaluate(
    ({ uid, urls }) => {
      const props = window.roamAlphaAPI.pull("[:block/props]", [":block/uid", uid]);
      const json = JSON.stringify(props ?? {});
      return Object.fromEntries(urls.map((u) => [u, json.includes(u)]));
    },
    { uid, urls: [FIRST_URL, EDITED_URL] },
  );

const iconState = (page) =>
  page.evaluate(() => {
    const anchor = document.querySelector(".tl-hyperlink-button");
    const text = document.querySelector('.tl-shape[data-shape-type="text"]');
    if (!anchor) return { present: false };
    const a = anchor.getBoundingClientRect();
    const t = text?.getBoundingClientRect();
    return {
      present: true,
      href: anchor.getAttribute("href"),
      hidden: anchor.classList.contains("tl-hyperlink-button__hidden"),
      clearOfText: t ? a.left >= t.right - 1 : null,
      verticalOffset: t ? Math.round(a.top + a.height / 2 - (t.top + t.height / 2)) : null,
    };
  });

// Escape does not deselect here; click empty canvas clear of the toolbars and menus.
